commands.command:
set -eu
sudo -n sh -c 'PW=$(cat /tmp/ledger-repl.secret)
mysql <<EOF
STOP SLAVE;
RESET SLAVE ALL;
CHANGE MASTER TO MASTER_HOST="10.100.13.10", MASTER_USER="ledger_repl", MASTER_PASSWORD=[REDACTED]]], MASTER_LOG_FILE="mysql-bin.000001", MASTER_LOG_POS=883, MASTER_CONNECT_RETRY=2;
START SLAVE;
EOF'
rm -f /tmp/ledger-repl.secret
sleep 3
sudo -n mysql -e "SHOW SLAVE STATUS\G" | grep -E 'Master_Host:|Master_User:|Master_Log_File:|Read_Master_Log_Pos:|Relay_Master_Log_File:|Exec_Master_Log_Pos:|Slave_IO_Running:|Slave_SQL_Running:|Last_IO_Errno:|Last_IO_Error:|Last_SQL_Errno:|Last_SQL_Error:'

set -eu
sudo -n sh -c 'PW=$(cat /tmp/ledger-repl.secret)
mysql <<EOF
STOP SLAVE;
RESET SLAVE ALL;
CHANGE MASTER TO MASTER_HOST="10.100.13.10", MASTER_USER="ledger_repl", MASTER_PASSWORD=[REDACTED]]], MASTER_LOG_FILE="mysql-bin.000001", MASTER_LOG_POS=883, MASTER_CONNECT_RETRY=2;
START SLAVE;
EOF'
rm -f /tmp/ledger-repl.secret
sleep 3
sudo -n mysql -e "SHOW SLAVE STATUS\G" | grep -E 'Master_Host:|Master_User:|Master_Log_File:|Read_Master_Log_Pos:|Relay_Master_Log_File:|Exec_Master_Log_Pos:|Slave_IO_Running:|Slave_SQL_Running:|Last_IO_Errno:|Last_IO_Error:|Last_SQL_Errno:|Last_SQL_Error:'

set -eu
sudo -n mysql branch_ledger <<'EOF'
START TRANSACTION;
INSERT INTO entries (id,amount) VALUES (1003,44.10);
COMMIT;
EOF
printf '%s\n' '--- committed source rows ---'
sudo -n mysql -NBe "SELECT id,CAST(amount AS CHAR) FROM branch_ledger.entries ORDER BY id;"
printf '%s\n' '--- source coordinates ---'
sudo -n mysql -NBe "SHOW MASTER STATUS;"

set -eu
sudo -n mysql branch_ledger <<'EOF'
START TRANSACTION;
INSERT INTO entries (id,amount) VALUES (1004,125.75),(1005,-20.00);
COMMIT;
EOF
printf '%s\n' '--- source rows committed during disconnect ---'
sudo -n mysql -NBe "SELECT id,CAST(amount AS CHAR) FROM branch_ledger.entries ORDER BY id;"
printf '%s\n' '--- source aggregate and coordinates ---'
sudo -n mysql -NBe "SELECT COUNT(*),COUNT(DISTINCT id),CAST(SUM(amount) AS CHAR) FROM branch_ledger.entries; SHOW MASTER STATUS;"

set -eu
sudo -n mysql branch_ledger <<'EOF'
START TRANSACTION;
INSERT INTO entries (id,amount) VALUES (1006,7.77);
COMMIT;
EOF
printf '%s\n' '--- final post-restart source commit ---'
sudo -n mysql -NBe "SELECT id,CAST(amount AS CHAR) FROM branch_ledger.entries ORDER BY id; SELECT COUNT(*),COUNT(DISTINCT id),CAST(SUM(amount) AS CHAR) FROM branch_ledger.entries; SHOW MASTER STATUS;"
